import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CardFooter
} from "@/components/ui/card";
import type { Attraction } from "@/lib/types";
import Image from "next/image";
import { Button } from "../ui/button";
import { MapPin } from "lucide-react";

type AttractionCardProps = {
  attraction: Attraction;
};


export function AttractionCard({ attraction }: AttractionCardProps) {
  const imageUrl = attraction.images[0] || "https://picsum.photos/seed/placeholder/400/300";

  return (
    <Card className="flex flex-col h-full overflow-hidden shadow-lg hover:shadow-xl transition-shadow duration-300">
      <CardHeader className="p-0">
        <div className="aspect-[4/3] relative bg-muted">
            <Image
              src={imageUrl}
              alt={attraction.name}
              fill
              className="object-cover"
            />
        </div>
      </CardHeader>
      <CardContent className="p-6 flex-grow">
        <CardTitle className="font-headline text-2xl mb-2">{attraction.name}</CardTitle>
        <CardDescription className="mt-4">{attraction.description}</CardDescription>
      </CardContent>
      <CardFooter className="p-6 pt-0">
        <Button asChild variant="secondary" className="w-full">
          <a
            href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(attraction.name || '')}`}
            target="_blank"
            rel="noopener noreferrer"
          >
            <MapPin className="mr-2 h-4 w-4" /> View on Map
          </a>
        </Button>
      </CardFooter>
    </Card>
  );
}
